import React from 'react';

function Photography() {
    return (
        <div className="p-5 sm:p-8 md:p-10 lg:p-16">
            <div className="flex flex-col sm:flex-row items-center sm:items-start space-y-4 sm:space-y-0 sm:space-x-4">
                <p className="underline text-base sm:text-lg md:text-xl lg:text-2xl cursor-pointer">Go Back</p>
                <h1 className="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-bold text-center sm:text-left sm:pl-10 md:pl-20 lg:pl-32">Photography</h1>
            </div>
            <p className="text-sm sm:text-base md:text-lg pl-2 sm:pl-5 mt-4 text-center sm:text-left">
                Some of my best photography over the course of 2 years.
            </p>
        </div>
    );
}

export default Photography;
